select jsonb_build_object(
'observed_at',now(),'stage',(select stage from memory_creative.installation where singleton),
'history',(select jsonb_agg(jsonb_build_object('version',version,'name',name,'sql_md5',md5(array_to_string(statements,''))) order by version) from supabase_migrations.schema_migrations where name in('memory_book_creative_presentation','memory_book_creative_mutations','memory_book_creative_public_contracts')),
'functions',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'signature',p.oid::regprocedure::text,'body_md5',md5(p.prosrc),'definition_md5',md5(pg_get_functiondef(p.oid)),'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'config',p.proconfig,'anon',has_function_privilege('anon',p.oid,'execute'),'app',has_function_privilege('authenticated',p.oid,'execute'),'service',has_function_privilege('service_role',p.oid,'execute'),'public_execute',exists(select 1 from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl where acl.grantee=0 and acl.privilege_type='EXECUTE')) order by n.nspname,p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='memory_creative' or p.oid in('public.get_memory_book_creative_capabilities()'::regprocedure,'public.create_memory_book_creative_presentation(uuid,text,text,text,text,uuid[],uuid,jsonb,jsonb)'::regprocedure,'public.save_memory_book_creative_presentation(uuid,integer,text,text,text,text,text,uuid,jsonb,jsonb)'::regprocedure,'public.get_memory_book(uuid)'::regprocedure,'public.get_memory_albums(uuid)'::regprocedure,'public.get_memory_album(uuid)'::regprocedure)),
'private_tables',(select jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'policy_count',(select count(*) from pg_policy where polrelid=c.oid),'anon',has_table_privilege('anon',c.oid,'SELECT,INSERT,UPDATE,DELETE'),'app',has_table_privilege('authenticated',c.oid,'SELECT,INSERT,UPDATE,DELETE'),'service',has_table_privilege('service_role',c.oid,'SELECT,INSERT,UPDATE,DELETE'))) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='memory_creative' and c.relkind='r'),
'owner_erasure_cascade',exists(select 1 from pg_constraint where conrelid='memory_creative.create_requests'::regclass and confrelid='public.profiles'::regclass and contype='f' and confdeltype='c'),
'columns',(select jsonb_agg(jsonb_build_object('name',column_name,'type',data_type,'nullable',is_nullable,'default',column_default) order by ordinal_position) from information_schema.columns where table_schema='public' and table_name='memory_albums' and column_name in('cover_artwork','film_settings','presentation_revision')),
'triggers',(select jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,'type',t.tgtype,'definition',pg_get_triggerdef(t.oid),'function_body_md5',md5(p.prosrc))) from pg_trigger t join pg_proc p on p.oid=t.tgfoid where t.tgrelid='public.memory_albums'::regclass and t.tgname in('memory_book_cover','memory_creative_presentation')),
'album_count',(select count(*) from public.memory_albums),
'album_existing_data_md5',(select md5(coalesce(string_agg(md5((to_jsonb(a)-array['cover_artwork','film_settings','presentation_revision'])::text),'' order by a.id),'')) from public.memory_albums a),
'page_count',(select count(*) from public.memory_pages),
'page_data_md5',(select md5(coalesce(string_agg(md5(to_jsonb(p)::text),'' order by p.id),'')) from public.memory_pages p),
'legacy_defaults',(select bool_and(film_settings->>'mode'='original' and film_settings->'titleCard'='false'::jsonb and presentation_revision=0) from public.memory_albums),
'requests',(select count(*) from memory_creative.create_requests),
'business_installed',to_regnamespace('business_auth') is not null,
'music_installed',to_regnamespace('music_library') is not null);
